@startuml

class Animal {
  + ID : long
  + name : string
  + breed : string
}

class Owner {
  + ID : long
  + name : string
  + address : string
  + phone : string
}

class Breed {
  + name : string
}

class Physician {
  + ID : long
  + name : string
  + address : string
  + phone : string
}

class Appointment {
  + startTime : datetime
}

class Condition {
  + commonName : string
  + scientificName : string
}

Owner "0..1" -- "*" Animal : owns
Breed "1" -- "*" Animal : describes
Breed "1" -- "*" Condition : common in
Animal "1" -- "*" Appointment : attends
Physician "1" -- "*" Appointment : responsible for
Appointment "*" -- "*" Condition : detects

@enduml

